{
  "name": "USBtin USB-CAN 适配器",
  "name_en": "USBtin USB-to-CAN Adapter",
  "manufacturer": "",
  "description": "USBtin 是一种通过串口命令控制的 USB 转 CAN 总线适配器，用于让计算机连接、监听和发送 CAN 报文。该设备支持设置 CAN 波特率与工作模式（如主动、只听、回环），并可配置 MCP2515 的寄存器、过滤器和掩码，适用于实验室中的 CAN 设备联机、总线监测、协议调试与嵌入式系统测试。",
  "description_en": "USBtin is a USB-to-CAN bus adapter controlled through serial commands, used to let a computer connect to, monitor, and transmit CAN frames. It supports CAN baud rate and mode configuration (such as active, listen-only, and loopback), and can configure MCP2515 registers, filters, and masks for laboratory CAN device interfacing, bus monitoring, protocol debugging, and embedded-system testing.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接指定串口上的 USBtin，并进入配置模式。",
      "description_en": "Connect to the USBtin on the specified serial port and enter configuration mode."
    },
    {
      "action_name": "auto-transmit",
      "description": "向 USBtin 发送原始命令。",
      "description_en": "Transmit a raw command to the USBtin."
    },
    {
      "action_name": "auto-read_response",
      "description": "读取 USBtin 返回的响应数据。",
      "description_en": "Read response data returned by the USBtin."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开设备连接并关闭串口。",
      "description_en": "Disconnect the device and close the serial port."
    },
    {
      "action_name": "auto-open_can_channel",
      "description": "设置 CAN 波特率和模式并打开 CAN 通道。",
      "description_en": "Set the CAN baud rate and mode, then open the CAN channel."
    },
    {
      "action_name": "auto-start_rx_thread",
      "description": "启动接收线程以处理串口中的 CAN 数据。",
      "description_en": "Start the receive thread to process CAN data from the serial port."
    },
    {
      "action_name": "auto-stop_rx_thread",
      "description": "停止接收线程并等待其退出。",
      "description_en": "Stop the receive thread and wait for it to exit."
    },
    {
      "action_name": "auto-rx_thread",
      "description": "运行主接收循环，解析接收数据、分发 CAN 消息并处理发送队列。",
      "description_en": "Run the main receive loop to parse incoming data, dispatch CAN messages, and handle the transmit queue."
    },
    {
      "action_name": "auto-close_can_channel",
      "description": "关闭 CAN 通道。",
      "description_en": "Close the CAN channel."
    },
    {
      "action_name": "auto-add_message_listener",
      "description": "添加接收 CAN 消息的回调监听器。",
      "description_en": "Add a callback listener for received CAN messages."
    },
    {
      "action_name": "auto-remove_message_listener",
      "description": "移除接收 CAN 消息的回调监听器。",
      "description_en": "Remove a callback listener for received CAN messages."
    },
    {
      "action_name": "auto-send_first_tx_fifo_message",
      "description": "发送发送队列中排在最前面的 CAN 消息。",
      "description_en": "Send the first CAN message in the transmit FIFO queue."
    },
    {
      "action_name": "auto-send",
      "description": "发送一条 CAN 消息。",
      "description_en": "Send a CAN message."
    },
    {
      "action_name": "auto-write_mcp_register",
      "description": "写入 MCP2515 控制器的指定寄存器。",
      "description_en": "Write the specified register of the MCP2515 controller."
    },
    {
      "action_name": "auto-write_mcp_filter_mask_registers",
      "description": "写入 MCP2515 的过滤掩码寄存器。",
      "description_en": "Write the MCP2515 filter mask registers."
    },
    {
      "action_name": "auto-write_mcp_filter_registers",
      "description": "写入 MCP2515 的消息过滤寄存器。",
      "description_en": "Write the MCP2515 message filter registers."
    },
    {
      "action_name": "auto-set_filter",
      "description": "配置 CAN 硬件过滤器和掩码。",
      "description_en": "Configure the CAN hardware filters and masks."
    }
  ],
  "tag_hints": [
    "USB-to-CAN",
    "CAN bus communication",
    "serial-controlled adapter",
    "MCP2515 filtering",
    "CAN message transmission",
    "listen-only CAN",
    "loopback testing"
  ]
}

